package org.concordia.babycdf;
import org.junit.jupiter.api.Test;import com.daml.ledger.api.v2.*;import java.util.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;import static org.concordia.babycdf.SourceCatalogueCodec.*;
class LiveIntegrationSchemaTest {
 @Test void canonicalConcreteCredentialAcceptsOnlyDeclaredShapeAndErrorsNeverBecomeEmpty()throws Exception{
  var sample=SourceCatalogueCodecTest.sample();var obs=observation(sample);var r=record("opener",ValueOuterClass.Value.newBuilder().setParty("opener").build(),"repo",text(REPOSITORY),"observation",obs,"fingerprint",text(SourceCatalogueDigest.digest(obs.getRecord())),"version",integer(1),"previousDigest",SourceOpenerLedger.none());var e=EventOuterClass.CreatedEvent.newBuilder().setContractId("exact-cid").addSignatories("opener").setCreateArguments(r.getRecord()).build();
  var decoded=CanonicalSourceCredential.decode(e,"opener");assertEquals("exact-cid",decoded.cid());assertEquals(1,decoded.version());assertEquals(sample,decoded.observation());
  for(String field:List.of("sourceSnapshot","pin","roundId","credential")){var bad=e.toBuilder().setCreateArguments(r.getRecord().toBuilder().addFields(ValueOuterClass.RecordField.newBuilder().setLabel(field).setValue(text("untrusted-secret")))).build();var failure=assertThrows(IntegrationStageFailure.class,()->CanonicalSourceCredential.decode(bad,"opener"));assertEquals("credential_decode",failure.getMessage());assertFalse(failure.toString().contains("untrusted-secret"));}
  var missing=e.toBuilder().setCreateArguments(r.getRecord().toBuilder().clearFields().addFields(r.getRecord().getFields(0))).build();assertThrows(IntegrationStageFailure.class,()->CanonicalSourceCredential.decode(missing,"opener"));assertThrows(IntegrationStageFailure.class,()->CanonicalSourceCredential.decode(e,"foreign"));
 }
 @Test void registryVersionSelectsCurrentWithHistoricalRetainedAndRejectsBadStates()throws Exception{
  var snapshot=new IntegratedAgendaSnapshot("cid","round","opener",184,"proposal","url","a".repeat(64),1,"a".repeat(64),"b".repeat(40),List.of(),false,null);
  var rules=new ArrayList<Reviewer.EffectiveRule>();for(int v:List.of(1,2)){String hash=RuleDocument.sha(Files.readAllBytes(Path.of("../rules/rule-v"+v+".json")));var ref=new RuleDocument.Ref("rules/rule-v"+v+".json",null,hash);var doc=RuleDocument.runtime(ref);rules.add(new Reviewer.EffectiveRule("v"+v,"architecture-review",v,doc.clauses(),ref,null));}
  class Gateway implements Reviewer.LedgerRuleGateway{long version=2;boolean duplicate,foreign,missing;public boolean registryBacked(){return true;}public List<Reviewer.EffectiveRule> activeRules(){return duplicate?List.of(rules.get(0),rules.get(1),rules.get(1)):rules;}public List<EventOuterClass.CreatedEvent> registryEvents(){if(missing)return List.of();String opener=foreign?"foreign":"opener";return List.of(EventOuterClass.CreatedEvent.newBuilder().setContractId("registry").addSignatories(opener).addWitnessParties(opener).setCreateArguments(record("opener",ValueOuterClass.Value.newBuilder().setParty(opener).build(),"version",integer(version)).getRecord()).build());}}
  var g=new Gateway();assertEquals(2,ActivatedRuleSelection.select(g,snapshot).version());g.duplicate=true;assertThrows(java.io.IOException.class,()->ActivatedRuleSelection.select(g,snapshot));g.duplicate=false;g.version=1;assertThrows(java.io.IOException.class,()->ActivatedRuleSelection.select(g,snapshot));g.version=3;assertThrows(java.io.IOException.class,()->ActivatedRuleSelection.select(g,snapshot));g.version=2;g.foreign=true;assertThrows(java.io.IOException.class,()->ActivatedRuleSelection.select(g,snapshot));g.foreign=false;g.missing=true;assertThrows(java.io.IOException.class,()->ActivatedRuleSelection.select(g,snapshot));
 }
}
